import base64,hashlib,hmac,math
from dataclasses import dataclass

def valid_clock(now):
    if type(now)not in(int,float)or not math.isfinite(now):raise ValueError("有限数值时钟，不接受bool/NaN/Inf")

def challenge(verifier):
    if type(verifier)is not str or not 43<=len(verifier)<=128:raise ValueError('verifier长度')
    allowed='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~'
    if any(c not in allowed for c in verifier):raise ValueError('verifier字符')
    return base64.urlsafe_b64encode(hashlib.sha256(verifier.encode()).digest()).rstrip(b'=').decode()
@dataclass(frozen=True)
class Enrollment:
    issuer:str
    client_id:str
    method:str
ISSUERS={'https://a.example/tenant','https://b.example'}
class Client:
    def __init__(self):self.enrollments={};self.codes={};self.refresh={};self.counter=0
    def enroll(self,issuer,portable_url,pre_registered=None,supports_cimd=True):
        if issuer not in ISSUERS:raise PermissionError('issuer不在可信策略中')
        # 已预配置的本issuer client_id优先，即使不支持CIMD也不能盲目切到DCR。
        method='pre_registered'if pre_registered else 'cimd'if supports_cimd else 'no_supported_enrollment'
        if method=='no_supported_enrollment':raise PermissionError('缺方法不静默降级')
        cid=pre_registered or portable_url
        if type(cid)is not str or not cid:raise ValueError('client ID')
        e=Enrollment(issuer,cid,method);self.enrollments[issuer]=e;return e
    def create_code(self,e,redirect,resource,verifier,now,owner='alice'):
        valid_clock(now)
        if self.enrollments.get(e.issuer)!=e:raise PermissionError('client必须按issuer独立enroll')
        self.counter+=1;code='code-'+str(self.counter)
        self.codes[code]={'enrollment':e,'redirect':redirect,'resource':resource,'pkce':challenge(verifier),
                          'owner':owner,'expiry':now+30,'used':False}
        return code
    def redeem(self,code,e,redirect,resource,verifier,owner,now):
        valid_clock(now)
        row=self.codes.get(code)
        if not row or row['used']or now>=row['expiry']:raise PermissionError('code无效/重放/过期')
        if (row['enrollment'],row['redirect'],row['resource'],row['owner'])!=(e,redirect,resource,owner):raise PermissionError('完整绑定不匹配')
        if not hmac.compare_digest(row['pkce'],challenge(verifier)):raise PermissionError('PKCE不匹配')
        row['used']=True # 所有条件满足后再consume；这里只是单进程字典，非并发原子服务。
        self.counter+=1;rt='refresh-'+str(self.counter)
        self.refresh[rt]={'enrollment':e,'resource':resource,'owner':owner,'used':False}
        return {'issuer':e.issuer,'aud':resource,'sub':owner,'refresh':rt}
    def rotate(self,rt,e,resource,owner):
        row=self.refresh.get(rt)
        if not row or row['used']or(row['enrollment'],row['resource'],row['owner'])!=(e,resource,owner):raise PermissionError('旧refresh/绑定无效')
        row['used']=True;self.counter+=1;new='refresh-'+str(self.counter)
        self.refresh[new]={**row,'used':False};return new

def callback_iss(selected,received,supported):
    if received is None:return not supported
    return type(received)is str and received==selected
