import base64,hashlib,hmac,json,math,re
from copy import deepcopy

def encode(value):return base64.urlsafe_b64encode(json.dumps(value,separators=(',',':'),allow_nan=False).encode()).rstrip(b'=').decode()
def decode(part):
    if type(part)is not str or not re.fullmatch(r'[A-Za-z0-9_-]+',part):raise ValueError('base64url格式')
    raw=base64.b64decode(part+'='*((-len(part))%4),altchars=b'-_',validate=True)
    def pairs(rows):
        out={}
        for k,v in rows:
            if k in out:raise ValueError('重复JSON键')
            out[k]=v
        return out
    def bad_constant(_):raise ValueError('非JSON数值常量')
    value=json.loads(raw,object_pairs_hook=pairs,parse_constant=bad_constant)
    if type(value)is not dict:raise ValueError('JOSE/claims对象')
    return value
KEYS={'https://a.example':{'k1':b'fixture-A-SECRET'},'https://b.example':{'k1':b'fixture-B-SECRET'}}

def mint(issuer,kid,claims,alg='HS256'):
    head=encode({'alg':alg,'typ':'JWT','kid':kid});body=encode(claims);signed=(head+'.'+body).encode()
    signature=base64.urlsafe_b64encode(hmac.new(KEYS[issuer][kid],signed,hashlib.sha256).digest()).rstrip(b'=').decode()
    return head+'.'+body+'.'+signature

def valid_number(x):return type(x)in(int,float)and math.isfinite(x)
def validate(token,expected_issuer,resource,now,needed_scope):
    if expected_issuer not in KEYS:raise PermissionError('issuer不可信，不按token任意联网取key')
    if type(token)is not str or len(token)>4096 or not valid_number(now):raise ValueError('token/clock')
    parts=token.split('.')
    if len(parts)!=3:raise ValueError('三段JWT')
    header,claims=decode(parts[0]),decode(parts[1])
    if set(header)!={'alg','typ','kid'}or header['alg']!='HS256'or header['typ']!='JWT':raise PermissionError('固定算法与head合同')
    kid=header['kid']
    if type(kid)is not str or kid not in KEYS[expected_issuer]:raise PermissionError('unknown kid，示例不自动rotate/mint')
    sig=base64.urlsafe_b64encode(hmac.new(KEYS[expected_issuer][kid],(parts[0]+'.'+parts[1]).encode(),hashlib.sha256).digest()).rstrip(b'=').decode()
    if not hmac.compare_digest(sig,parts[2]):raise PermissionError('signature不匹配')
    if claims.get('iss')!=expected_issuer or type(claims.get('sub'))is not str or not claims['sub']:raise PermissionError('issuer/subject')
    aud=claims.get('aud');audiences=[aud]if type(aud)is str else aud
    if type(audiences)is not list or not audiences or any(type(v)is not str for v in audiences)or resource not in audiences:raise PermissionError('aud/resource')
    exp,nbf=claims.get('exp'),claims.get('nbf',0)
    if not valid_number(exp)or not valid_number(nbf)or now>=exp or now<nbf:raise PermissionError('exp/nbf类型/时间')
    scope=claims.get('scope')
    if type(scope)is not str or needed_scope not in scope.split():raise PermissionError('scope')
    return {'principal':claims['sub'],'issuer':expected_issuer,'resource':resource,'scope':set(scope.split())}

