class Introspection:
    def __init__(self):self.cache={};self.active=True;self.calls=0
    def read(self,issuer,token_id,resource,now):
        key=(issuer,hashlib.sha256(token_id.encode()).hexdigest(),resource)
        if key in self.cache and now<self.cache[key][0]:return deepcopy(self.cache[key][1])
        if type(self.active)is not bool:raise ValueError('introspection active必须boolean')
        self.calls+=1;result={'active':self.active and now<130,'exp':130,'aud':resource,'sub':'alice'}
        ttl=min(5,max(0,result['exp']-now))
        if result['active']:self.cache[key]=(now+ttl,deepcopy(result))
        else:self.cache.pop(key,None)
        return result
